"""Informe HTML local reproducible a partir de indicadores agregados y catálogo."""
import html
from collections import defaultdict


def render_local_report(payload, catalog):
    escape=lambda v: html.escape(str(v))
    years=defaultdict(list)
    for p in payload.get('profiles',[]):
        years[p['year']].append(p)
    body=[]
    for year, profiles in sorted(years.items()):
        records=sum(p['records'] for p in profiles)
        body.append('<tr>'+''.join(f'<td>{escape(v)}</td>' for v in [year,f'{records:,}',len(profiles),min(p['date_min'] for p in profiles),max(p['date_max'] for p in profiles),f'{sum(p["hours_known"] for p in profiles)/records:.1%}',f'{sum(p["coordinates_plausible"] for p in profiles)/records:.1%}'])+'</tr>')
    sources=''.join(f'<li>{escape(s["id"])} — <a href="{escape(s.get("url") or "#")}">Fuente</a> — {escape(s.get("license"))}</li>' for s in payload['sources'])
    return f'''<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex"><title>OSV-NL · Informe de cobertura y calidad</title><style>body{{font:16px/1.7 system-ui;background:#f1f5f9;color:#18334d;max-width:1200px;margin:auto;padding:36px}}h1{{font-size:34px}}table{{border-collapse:collapse;width:100%;font-size:13px}}td,th{{border-bottom:1px solid #cbd5e1;padding:12px;text-align:left}}.notice{{padding:20px;background:#e0f2f1;border-left:4px solid #0d9488}}.scroll{{overflow:auto}}a{{color:#075985}}li{{margin:12px 0}}@media print{{body{{padding:0;background:white;font-size:11px}}table{{font-size:10px}}}}</style></head><body><p>OSV—NL · Inteligencia territorial para proteger la vida.</p><h1>Informe de cobertura y calidad RATIV</h1><p class="notice"><strong>Documento local. No autorizado para publicación.</strong> Registros reportados; no garantiza siniestros únicos ni exhaustividad. Iniciativa ciudadana independiente de OCISEVI y del gobierno.</p><p>Fecha de corte del evento: {escape(payload['data_through'])}. Pipeline: {escape(payload['generated_at'])}.</p><h2>Cobertura temporal y territorial observada</h2><div class="scroll"><table><thead><tr><th>Año</th><th>Registros</th><th>Municipios</th><th>Primera fecha</th><th>Última fecha</th><th>Hora de reporte conocida</th><th>Coordenadas plausibles</th></tr></thead><tbody>{''.join(body)}</tbody></table></div><h2>Hallazgos y limitaciones</h2><ul>{''.join('<li>'+escape(x)+'</li>' for x in payload['limitations'])}</ul><p>El folio ENCUESTA se repite ampliamente en 2019–2022; se conservan registros con identificador técnico único y no se deduplica por folio. Las 200 filas exactas repetidas de 2019 requieren conciliación con la fuente, no eliminación automática.</p><h2>Método</h2><p>Una fila por registro RATIV. Fecha reconstruida desde año, mes y día; día de la semana calculado desde fecha. Códigos de sin dato preservados como nulos. Hora de reporte HH:MM[:SS] o fracción Excel del día; seriales con fecha ambiguos excluidos. Pares geográficos estrictos, extensión regional aproximada; datum no declarado. Sin geocodificación de texto libre ni imputación.</p><p>El navegador recibe agregados. Teléfonos, placas, pólizas, folios y narraciones no se exportan. Umbral mensual mínimo cinco; personas entre una y cuatro se suprimen. Desgloses locales sujetos a revisión conjunta contra reconstrucción antes de publicación. H3 resolución 8, umbral diez; rankings de calles con mínimo veinte. Ninguna concentración se denomina riesgo sin exposición.</p><h2>Fuentes</h2><ul>{sources}</ul><h2>Referencias y reproducibilidad</h2><p>Catálogo de códigos OCISEVI y Diccionario de datos RATIV, descargados con SHA-256 en el manifiesto de adquisición local. Se preservan originales comprimidos. El pipeline y la configuración del repositorio regeneran este informe. Tablas auditadas: {sum(c['status']=='audited' for c in catalog)}. Consulte METHODOLOGY.md y docs/RATIV_ADAPTER.md para decisiones y límites.</p></body></html>'''
